import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/registry/ndeko/ui/accordion';
import { Button } from '@/registry/ndeko/ui/button';

import { QUESTION_GROUPS, SECTION } from './data';

const FIRST_QUESTION_ID = QUESTION_GROUPS[0].questions[0].id;

export default function Faqs01() {
  return (
    <section className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'>
      <div className='mx-auto grid max-w-6xl gap-10 lg:grid-cols-[minmax(0,2fr)_minmax(0,3fr)] lg:gap-16'>
        <div className='flex flex-col items-start gap-6 lg:sticky lg:top-12 lg:self-start'>
          <div className='flex flex-col gap-3'>
            <h2 className='text-2xl font-semibold text-balance sm:text-3xl'>
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground max-w-sm text-base text-pretty'>
              {SECTION.description}
            </p>
          </div>
          <nav aria-label='Question topics' className='hidden lg:block'>
            <ul className='flex flex-col gap-0.5'>
              {QUESTION_GROUPS.map((group) => (
                <li key={group.id}>
                  <a
                    href={`#${group.id}`}
                    className='text-muted-foreground hover:text-foreground hover:bg-foreground/5 focus-visible:ring-ring/25 -mx-2 flex h-8 items-center rounded-md px-2 text-[13px] transition-colors outline-none focus-visible:ring-[3px]'
                  >
                    {group.title}
                  </a>
                </li>
              ))}
            </ul>
          </nav>
          <Button
            variant='outline'
            nativeButton={false}
            render={<a href={SECTION.contactHref} />}
          >
            {SECTION.contactLabel}
          </Button>
        </div>
        <div className='flex flex-col gap-10'>
          {QUESTION_GROUPS.map((group) => (
            <section
              key={group.id}
              id={group.id}
              aria-labelledby={`${group.id}-title`}
              className='flex scroll-mt-8 flex-col gap-1'
            >
              <h3
                id={`${group.id}-title`}
                className='text-primary-ink text-xs font-medium'
              >
                {group.title}
              </h3>
              <Accordion defaultValue={[FIRST_QUESTION_ID]}>
                {group.questions.map((item) => (
                  <AccordionItem key={item.id} value={item.id}>
                    <AccordionTrigger className='text-sm'>
                      {item.question}
                    </AccordionTrigger>
                    <AccordionContent className='text-sm leading-relaxed text-pretty'>
                      {item.answer}
                    </AccordionContent>
                  </AccordionItem>
                ))}
              </Accordion>
            </section>
          ))}
        </div>
      </div>
    </section>
  );
}

export type Question = {
  id: string;
  question: string;
  answer: string;
};

export type QuestionGroup = {
  id: string;
  title: string;
  questions: Question[];
};

export const SECTION = {
  title: 'Questions teams ask before switching',
  description:
    'Short answers about moving to Driftdesk. If yours is missing, the support team answers it by email.',
  contactLabel: 'Write to support',
  contactHref: 'mailto:support@driftdesk.example',
};

export const QUESTION_GROUPS: QuestionGroup[] = [
  {
    id: 'faqs-01-getting-started',
    title: 'Getting started',
    questions: [
      {
        id: 'import',
        question: 'Can we bring our old conversations with us?',
        answer:
          'Yes. Connect your current inbox and Driftdesk imports the last twelve months of conversations, with their tags and their authors.',
      },
      {
        id: 'setup',
        question: 'How long does the setup take?',
        answer:
          'Forwarding your support address and inviting the team is enough to start. Routing rules and saved replies can come later.',
      },
      {
        id: 'channels',
        question: 'Which channels can we answer from Driftdesk?',
        answer:
          'Email, the chat widget on your site and contact forms. Each conversation keeps its channel, so replies leave the way the message came in.',
      },
    ],
  },
  {
    id: 'faqs-01-billing',
    title: 'Billing',
    questions: [
      {
        id: 'seats',
        question: 'Do we pay for people who only read?',
        answer:
          'No. A seat is someone who replies to customers. Teammates who read conversations and leave private notes are free.',
      },
      {
        id: 'cancel',
        question: 'What happens to our data if we cancel?',
        answer:
          'You can export every conversation as CSV or JSON for thirty days after cancelling. After that the workspace is deleted.',
      },
    ],
  },
  {
    id: 'faqs-01-security',
    title: 'Data and security',
    questions: [
      {
        id: 'storage',
        question: 'Where are conversations stored?',
        answer:
          'In the region you pick when you create the workspace. Attachments stay in the same region as the messages they belong to.',
      },
      {
        id: 'access',
        question: 'Can we limit who sees which inbox?',
        answer:
          'Yes. Each inbox has its own members, and an admin can hide an inbox from everyone who is not on it.',
      },
    ],
  },
];
